.goal__top { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; flex-wrap: wrap; }
.goal__value { font-size: 28px; font-weight: 600; letter-spacing: -0.015em; }
.goal__of { font-size: 12px; color: var(--ink-2); font-variant-numeric: tabular-nums; }
.meter { --fill: var(--series-1); height: 8px; border-radius: 4px; background: color-mix(in srgb, var(--fill) 20%, var(--surface)); overflow: hidden; }
.meter_warn { --fill: #e09a00; }
.meter_bad { --fill: var(--bad-text); }
.meter__fill { height: 100%; background: var(--fill); border-radius: 4px; transition: width 300ms ease; }
.goal__status { display: flex; align-items: center; flex-wrap: wrap; gap: 4px; font-size: 12px; font-weight: 600; }
.goal__status_ok { color: var(--good-text); }
.goal__status_warn { color: var(--warn-text); }
.goal__status_bad { color: var(--bad-text); }
.goal__hint { font-weight: 400; color: var(--muted); }
@container widget (max-height: 90px) { .goal { gap: 6px; } .goal__hint { display: none; } .goal__value { font-size: 22px; } }

/* ---------- Тепловая карта ---------- */
.heat { display: flex; flex-direction: column; gap: 8px; }
.heat__body { position: relative; flex: 1; min-height: 0; display: flex; outline: none; }
.heat__body:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; border-radius: 4px; }
.heat__grid { flex: 1; display: grid; grid-template-rows: 16px repeat(7, minmax(0, 1fr)); gap: 2px; min-height: 0; }
.heat__col, .heat__row { font-size: 11px; color: var(--muted); display: flex; align-items: center; }
.heat__col { justify-content: center; }
.heat__cell { border-radius: 4px; min-height: 0; transition: outline-color 100ms; outline: 2px solid transparent; outline-offset: -1px; }
.heat__cell_on { outline-color: var(--ink); }
.heat__legend { flex: none; display: flex; align-items: center; gap: 8px; font-size: 11px; color: var(--muted); }
.heat__ramp { width: 80px; height: 8px; border-radius: 4px; background: linear-gradient(90deg, var(--heat-lo), var(--heat-hi)); }

/* ---------- Таблица заказов ---------- */
.orders { overflow: auto; margin: 0 -16px; padding: 0 16px; }
.orders__table { width: 100%; border-collapse: collapse; font-size: 13px; }
.orders__table th {
  position: sticky; top: 0; z-index: 1; background: var(--surface); text-align: left;
  font-size: 11px; font-weight: 600; color: var(--muted); padding: 4px 8px 6px 0; border-bottom: 1px solid var(--axis);
}
.orders__table td { padding: 7px 8px 7px 0; border-bottom: 1px solid var(--grid); white-space: nowrap; }
.orders__table tr:last-child td { border-bottom: 0; }
.orders__id { color: var(--ink-2); font-variant-numeric: tabular-nums; }
.orders__num { text-align: right !important; font-variant-numeric: tabular-nums; padding-right: 16px !important; }
@container widget (max-width: 460px) { .orders__channel { display: none; } }
EOF
cd .. && npx tsc --noEmit 2>&1 | head -30

args.command:
(npx vite --port 5199 --strictPort > /tmp/vite.log 2>&1 &) ; sleep 3; cat > /tmp/pw/shot.mjs <<'EOF'
import { chromium } from 'playwright';
const b = await chromium.launch();
const p = await b.newPage({ viewport: { width: 1280, height: 900 } });
const errs = [];
p.on('console', m => { if (['error','warning'].includes(m.type())) errs.push(m.text()); });
p.on('pageerror', e => errs.push('PAGEERROR ' + e.message));
await p.goto('http://localhost:5199/');
await p.waitForSelector('.wf');
await p.waitForTimeout(600);
await p.screenshot({ path: '/tmp/pw/1-initial.png' });

const rect = async (t) => p.evaluate((t) => { const s=[...document.querySelectorAll('.wf')].find(e=>e.getAttribute('aria-label')===t); const r=s.parentElement.getBoundingClientRect(); return {x:Math.round(r.x),y:Math.round(r.y),w:Math.round(r.width),h:Math.round(r.height)}; }, t);

// drag "Последние заказы" header onto the top-left
const before = await rect('Последние заказы');
const head = await p.locator('section[aria-label="Последние заказы"] .wf__head').boundingBox();
await p.mouse.move(head.x + 100, head.y + 20);
await p.mouse.down();
await p.mouse.move(head.x + 60, head.y - 200, { steps: 8 });
await p.mouse.move(head.x - 300, head.y - 520, { steps: 8 });
await p.screenshot({ path: '/tmp/pw/2-dragging.png' });
await p.mouse.up();
await p.waitForTimeout(500);
console.log('orders before', before, 'after', await rect('Последние заказы'), 'revenue-kpi', await rect('Выручка'));
await p.screenshot({ path: '/tmp/pw/3-dropped.png' });

// resize chart
const ch = await rect('Выручка по дням');
const rs = await p.locator('section[aria-label="Выручка по дням"] .wf__resize').boundingBox();
await p.mouse.move(rs.x + 10, rs.y + 10); await p.mouse.down();
await p.mouse.move(rs.x - 200, rs.y + 10, { steps: 6 }); await p.mouse.up();
await p.waitForTimeout(400);
console.log('chart', ch, '->', await rect('Выручка по дням'));

// hover chart
const area = await p.locator('section[aria-label="Выручка по дням"] .chart__area').boundingBox();
await p.mouse.move(area.x + area.width * 0.6, area.y + area.height * 0.4);
await p.waitForTimeout(200);
await p.screenshot({ path: '/tmp/pw/4-hover.png' });

// keyboard move
await p.locator('section[aria-label="Средний чек"] .wf__grip').focus();
const k0 = await rect('Средний чек');
await p.keyboard.press('ArrowDown'); await p.waitForTimeout(400);
console.log('kbd', k0, await rect('Средний чек'));

// remove + add
await p.locator('section[aria-label="Конверсия"]').hover();
await p.locator('section[aria-label="Конверсия"] .wf__close').click();
await p.waitForTimeout(400);
console.log('widgets', await p.locator('.wf').count());
await p.getByText('Добавить виджет').click();
await p.waitForTimeout(200);
await p.screenshot({ path: '/tmp/pw/5-menu.png' });
await p.getByText('Конверсия', { exact: true }).last().click();
await p.waitForTimeout(400);
console.log('widgets', await p.locator('.wf').count());
// reload persistence
await p.reload(); await p.waitForSelector('.wf'); await p.waitForTimeout(400);
console.log('after reload orders', await rect('Последние заказы'));
await p.setViewportSize({ width: 600, height: 900 }); await p.waitForTimeout(400);
await p.screenshot({ path: '/tmp/pw/6-mobile.png' });
console.log('errors', errs);
await b.close();
EOF
cd /tmp/pw && node shot.mjs

