    const limits = { minW: 3, minH: 2, maxW: 8 };
    expect(get(resizeItem(base(), 'b', 20, 4, limits), 'b')).toMatchObject({ w: 6, h: 4 });
    expect(get(resizeItem(base(), 'a', 1, 1, limits), 'a')).toMatchObject({ w: 3, h: 2 });
